{"code":"def solve(x):
    if not x:
        return []
    intervals = sorted(([iv[0], iv[1]] for iv in x), key=lambda v: v[0])
    merged = []
    for start, end in intervals:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            if end > merged[-1][1]:
                merged[-1][1] = end
    return merged
