{"code":"def solve(x):
    nodes = x.get("nodes", [])
    edges = x.get("edges", [])

    indegree = {}
    adj = {}

    for node in nodes:
        indegree[node] = 0
        adj[node] = []

    for edge in edges:
        if not (isinstance(edge, list) or isinstance(edge, tuple)):
            continue
        if len(edge) != 2:
            continue
        u, v = edge
        if u not in indegree:
            indegree[u] = 0
            adj[u] = []
        if v not in indegree:
            indegree[v] = 0
            adj[v] = []
        adj[u].append(v)
        indegree[v] += 1

    zero_indegree = []
    for node in indegree:
        if indegree[node] == 0:
            zero_indegree.append(node)

    result = []
    total = len(indegree)

    while zero_indegree:
        current_min = zero_indegree[0]
        for node in zero_indegree[1:]:
            if node < current_min:
                current_min = node

        new_zero = []
        removed = False
        for node in zero_indegree:
            if not removed and node == current_min:
                removed = True
                continue
            new_zero.append(node)
        zero_indegree = new_zero

        result.append(current_min)
        for v in adj.get(current_min, []):
            indegree[v] -= 1
            if indegree[v] == 0:
                zero_indegree.append(v)

    if len(result) != total:
        return None
    return result
"}

