{"code":"def solve(x):
    coins = x.get('coins', [])
    amount = x.get('amount', 0)
    if amount == 0:
        return 0
    if not coins:
        return -1
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for c in coins:
        if c <= 0:
            continue
        for a in range(c, amount + 1):
            prev = dp[a - c]
            if prev + 1 < dp[a]:
                dp[a] = prev + 1
    return dp[amount] if dp[amount] <= amount else -1"}

