{"code":"def solve(x):
    # Make a shallow copy of intervals so x is not mutated
    intervals = [[interval[0], interval[1]] for interval in x]

    if not intervals:
        return []

    # Sort intervals by start value
    intervals = sorted(intervals, key=lambda v: v[0])

    merged = [intervals[0]]

    for s, e in intervals[1:]:
        last = merged[-1]
        # Merge if overlapping or touching: s <= last[1]
        if s <= last[1]:
            if e > last[1]:
                last[1] = e
        else:
            merged.append([s, e])

    return merged
"}

{"code":"def solve(x):
    coins = x.get("coins", [])
    amount = x.get("amount", 0)

    if amount == 0:
        return 0
    if not coins:
        return -1

    max_val = amount + 1
    dp = [max_val] * (amount + 1)
    dp[0] = 0

    for c in coins:
        if c <= 0:
            continue
        for a in range(c, amount + 1):
            if dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1

    return dp[amount] if dp[amount] != max_val else -1
"}

