{"code":"def solve(x):
    nodes = x['nodes']
    edges = x['edges']

    # Build adjacency list and in-degree count
    graph = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for src, dst in edges:
        graph[src].append(dst)
        in_degree[dst] += 1

    # Initialize queue with all nodes having in-degree 0
    from collections import deque
    queue = deque()
    for node in nodes:
        if in_degree[node] == 0:
            queue.append(node)

    # Sort queue lexicographically
    queue = deque(sorted(queue))

    result = []

    while queue:
        # Get the lexicographically smallest node
        node = queue.popleft()
        result.append(node)

        # Reduce in-degree of neighbors
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

        # Re-sort queue to maintain lexicographical order
        queue = deque(sorted(queue))

    # Check if all nodes are included (no cycle)
    if len(result) != len(nodes):
        return None

    return result"}

