        all_nodes.add(s)
        all_nodes.add(t)

    adj = {}
    indeg = {}
    for n in all_nodes:
        adj[n] = []
        indeg[n] = 0

    for e in edges:
        if not isinstance(e, (list, tuple)) or len(e) != 2:
            continue
        s, t = e
        if s not in adj:
            adj[s] = []
            indeg[s] = indeg.get(s, 0)
        if t not in adj:
            adj[t] = []
            indeg[t] = indeg.get(t, 0)
        adj[s].append(t)
        indeg[t] = indeg.get(t, 0) + 1

    zero = []
    for n in adj:
        if indeg.get(n, 0) == 0:
            zero.append(n)

    result = []
    while zero:
        u = min(zero)
        zero.remove(u)
        result.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                zero.append(v)

    if len(result) != len(adj):
        return None
    return result
"}

{"code":"def solve(x):
