{"code":"def solve(x):
    nodes_input = x.get("nodes")
    edges = x.get("edges")
    if nodes_input is None:
        nodes_input = []
    if edges is None:
        edges = []
    in_deg = {}
    adj = {}
    nodes_list = []
    for n in nodes_input:
        if n not in in_deg:
            in_deg[n] = 0
            adj[n] = []
            nodes_list.append(n)
    for e in edges:
        if not e or len(e) < 2:
            continue
        u = e[0]
        v = e[1]
        if u not in in_deg:
            in_deg[u] = 0
            adj[u] = []
            nodes_list.append(u)
        if v not in in_deg:
            in_deg[v] = 0
            adj[v] = []
            nodes_list.append(v)
        adj[u].append(v)
        in_deg[v] += 1
    zero_in = []
    for n in nodes_list:
        if in_deg.get(n, 0) == 0:
            zero_in.append(n)
    order = []
    while zero_in:
        m = zero_in[0]
        for z in zero_in[1:]:
            if z < m:
                m = z
        new_zero = []
        for z in zero_in:
            if z != m:
                new_zero.append(z)
        zero_in = new_zero
        order.append(m)
        for nei in adj.get(m, []):
            in_deg[nei] -= 1
            if in_deg[nei] == 0:
                zero_in.append(nei)
    if len(order) != len(nodes_list):
        return None
    return order
"}

